using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpWeatherServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor-injected dependencies — the MCP SDK resolves these from the DI container.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_forecast"),
     Description("Get the weather forecast for a location using latitude and longitude.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        // Step 1: Resolve the grid point for the coordinates.
        var pointUrl = $"/points/{latitude:F4},{longitude:F4}";
        using var pointDoc = await client.GetFromJsonAsync<JsonDocument>(pointUrl);
        var forecastUrl = pointDoc!.RootElement
            .GetProperty("properties")
            .GetProperty("forecast")
            .GetString()!;

        // Step 2: Fetch the actual forecast.
        using var forecastDoc = await client.GetFromJsonAsync<JsonDocument>(forecastUrl);
        var periods = forecastDoc!.RootElement
            .GetProperty("properties")
            .GetProperty("periods")
            .EnumerateArray()
            .Take(5);

        return string.Join("\n---\n", periods.Select(p =>
            $"{p.GetProperty("name").GetString()}: " +
            $"{p.GetProperty("temperature").GetInt32()}°{p.GetProperty("temperatureUnit").GetString()} — " +
            $"{p.GetProperty("detailedForecast").GetString()}"));
    }

    [McpServerTool(Name = "get_alerts"),
     Description("Get active weather alerts for a US state (two-letter code, e.g. CA, NY).")]
    public async Task<string> GetAlertsAsync(
        [Description("Two-letter US state code")] string state)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");
        using var doc = await client.GetFromJsonAsync<JsonDocument>(
            $"/alerts/active/area/{state}");

        var alerts = doc!.RootElement
            .GetProperty("features")
            .EnumerateArray()
            .Take(5)
            .Select(f =>
            {
                var props = f.GetProperty("properties");
                return $"[{props.GetProperty("severity").GetString()}] " +
                       $"{props.GetProperty("event").GetString()}\n" +
                       $"{props.GetProperty("headline").GetString()}";
            });

        var result = string.Join("\n---\n", alerts);
        return string.IsNullOrEmpty(result) ? "No active alerts for this state." : result;
    }
}

